```c
#include <stdio.h>

#define MAX_N 100
#define INF (1LL << 60)

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    int cost[MAX_N][MAX_N] = {{0}};
    for (int i = 0; i < m; i++) {
        int a, b, c;
        scanf("%d %d %d", &a, &b, &c);
        --a;
        --b;
        if (cost[a][b] == 0 || c < cost[a][b]) {
            cost[a][b] = cost[b][a] = c;
        }
    }

    long long dist[MAX_N];
    int visited[MAX_N] = {0};

    for (int i = 0; i < n; i++) dist[i] = INF;
    dist[0] = 0;

    for (int step = 0; step < n; step++) {
        int u = -1;
        for (int i = 0; i < n; i++) {
            if (!visited[i] && (u == -1 || dist[i] < dist[u])) {
                u = i;
            }
        }

        if (u == -1 || dist[u] == INF) break;
        visited[u] = 1;

        for (int v = 0; v < n; v++) {
            if (cost[u][v] > 0 && dist[u] + cost[u][v] < dist[v]) {
                dist[v] = dist[u] + cost[u][v];
            }
        }
    }

    printf("%lld\n", dist[n - 1]);
    return 0;
}
```

